.podium-card { position: relative; min-height: 220px; padding: 28px 24px 24px; display: flex; flex-direction: column; overflow: hidden; color: var(--red); background: var(--podium-light); text-transform: uppercase; }
.podium-card--second { min-height: 260px; background: var(--podium-pink); order: -1; }
