.podium-decor { position: absolute; right: -30px; bottom: -10px; width: 156px; height: 248px; }
.podium-decor img { width: 156px; height: 248px; max-width: none; }
.podium-card:not(.podium-card--first) .podium-decor, .podium-card:not(.podium-card--first) .podium-decor img { width: 147px; height: 223px; }
.podium-card:not(.podium-card--first) .podium-decor { right: -25px; }
.podium-avatar { position: absolute; z-index: 1; left: 24px; bottom: 92px; width: 64px; height: 64px; border-radius: var(--radius-round); object-fit: cover; }
.podium-place { position: relative; z-index: 1; font-size: 14px; letter-spacing: .05em; }
.podium-card h3 { position: relative; z-index: 1; margin-top: auto; font-size: 24px; line-height: 32px; }
.podium-score { position: relative; z-index: 1; margin-top: 4px; font-size: 14px; font-weight: 700; }
.leaderboard-list { list-style: none; margin: 48px auto 64px; padding: 0; max-width: 1200px; text-align: left; }
.leaderboard-list li { min-height: 72px; display: flex; align-items: center; gap: 18px; padding: 8px 24px; background: #ffffffb0; }
.leaderboard-list li:nth-child(odd) { background: transparent; }
.rank { min-width: 24px; font-size: 32px; font-weight: 700; color: var(--text); }
.leaderboard-list img { width: 48px; height: 48px; object-fit: cover; border-radius: var(--radius-round); }
.player-name { font-size: 20px; line-height: 24px; font-weight: 700; text-transform: uppercase; }
.player-score { margin-left: auto; font-size: 14px; font-weight: 700; white-space: nowrap; }

.mechanics { position: relative; overflow: hidden; padding: var(--space-20) 0 120px; text-align: center; background: var(--paper); }
.mechanics h2 { margin-top: var(--space-4); font-size: var(--section-title-size); line-height: var(--section-title-leading); text-transform: uppercase; }
.mechanics h2 span { color: var(--red); }
.mechanics-diagram { position: relative; max-width: 800px; margin: 99px auto 0; }
.mechanics-list { list-style: none; margin: 0; padding: 0; text-align: left; }
.mechanics-list li { display: grid; grid-template-columns: 1fr 1fr; gap: 44px; align-items: start; min-height: 340px; }
.mechanics-list li:last-child { min-height: 240px; }
.mechanics-list strong { text-align: right; color: var(--coral); font-size: 240px; line-height: 1; letter-spacing: -.04em; }
